import bisect
from collections import defaultdict

class Solution:
    def isSubsequence(self, s: str, t: str) -> bool:
        idx = defaultdict(list)
        for i, c in enumerate(t):
            idx[c].append(i)
        prev = -1
        for c in s:
            positions = idx.get(c)
            if not positions:
                return False
            j = bisect.bisect_right(positions, prev)
            if j == len(positions):
                return False
            prev = positions[j]
        return True

